import { Router } from "express";
import { authMiddleware } from "../../../middlewares/authMiddleware.js";
import CreateBannerController from "../controllers/CreateBannerController.js";
import ListBannerController from "../controllers/ListBannerController.js";
import UpdateBannerController from "../controllers/UpdateBannerController.js";
import DeleteBannerController from "../controllers/DeleteBannerController.js";
import { adminMiddleware } from "../../../middlewares/adminMiddleware.js";
import { billingMiddleware } from "../../../middlewares/billingMiddleware.js";
const router = Router();
router.post("/", authMiddleware, adminMiddleware, billingMiddleware, (req, res) => CreateBannerController.handle(req, res));
router.get("/", authMiddleware, adminMiddleware, (req, res) => ListBannerController.handle(req, res));
router.put("/:id", authMiddleware, adminMiddleware, (req, res) => UpdateBannerController.handle(req, res));
router.delete("/:id", authMiddleware, adminMiddleware, (req, res) => DeleteBannerController.handle(req, res));
export default router;
